static juce::Component* find(juce::Component& root,const juce::String& id){if(root.getComponentID()==id||root.getName()==id)return &root;for(auto* c:root.getChildren())if(auto* r=find(*c,id))return r;return nullptr;}
static juce::TextButton* key(juce::Component& root,const char* id){auto* b=dynamic_cast<juce::TextButton*>(find(root,id));if(!b||!b->onClick)throw std::runtime_error("Missing key");return b;}
static juce::TextEditor* field(juce::Component& root){auto* t=dynamic_cast<juce::TextEditor*>(find(root,"tempo-input"));if(!t)throw std::runtime_error("Missing field");return t;}
static std::unique_ptr<juce::AudioProcessorEditor> open(HonestMixAudioProcessor& p){auto e=std::unique_ptr<juce::AudioProcessorEditor>(p.createEditor());e->getProperties().set("headlessTest",true);key(*e,"tempo")->onClick();return e;}
static auto& editor(juce::AudioProcessorEditor& e){auto* p=dynamic_cast<HonestMixAudioProcessorEditor*>(&e);if(!p)throw std::runtime_error("Unexpected editor");return *p;}
static void text(juce::Component& e,const char* value){field(e)->setText(value,false);field(e)->onTextChange();}
static void load(HonestMixAudioProcessor& p,const juce::XmlElement& xml){juce::MemoryBlock bytes;juce::AudioProcessor::copyXmlToBinary(xml,bytes);p.setStateInformation(bytes.getData(),(int)bytes.getSize());}
